export function getStyleTemplate(id: string): StyleTemplate | undefined {
  return styleTemplates[id];
}

export function getAllStyleTemplates(): StyleTemplate[] {
  return Object.values(styleTemplates);
}

export function getTemplateDecoratorSuggestions(templateId: string): any {
  return TEMPLATE_DECORATOR_SUGGESTIONS[templateId] || {};
}