import { PillarTheme, PillarId } from '@/types/pillar';
import { p1Framework } from './p1-framework';
import { p2Strategy } from './p2-strategy';
import { p3Systems } from './p3-systems';
import { p4Capital } from './p4-capital';
import { p5Vitality } from './p5-vitality';
import { p6Sovereignty } from './p6-sovereignty';

export const pillars: Record<PillarId, PillarTheme> = {
  p1: p1Framework,
  p2: p2Strategy,
  p3: p3Systems,
  p4: p4Capital,
  p5: p5Vitality,
  p6: p6Sovereignty,
};

export const pillarList: PillarTheme[] = Object.values(pillars);

export function getPillarTheme(id: PillarId): PillarTheme {
  return pillars[id];
}

